import java.util.*;

class Solution {
    public int numberOfArithmeticSlices(int[] nums) {
        int n = nums.length;
        Map<Long, Integer>[] dp = new HashMap[n];
        int answer = 0;
        for (int i = 0; i < n; i++) {
            dp[i] = new HashMap<>();
            for (int j = 0; j < i; j++) {
                long diff = (long) nums[i] - (long) nums[j];
                int extend = dp[j].getOrDefault(diff, 0);
                int current = dp[i].getOrDefault(diff, 0);
                answer += extend;
                dp[i].put(diff, current + extend + 1);
            }
        }
        return answer;
    }
}

