class Solution {
    public int numberOfArithmeticSlices(int[] nums) {
        int n = nums.length;
        Map<Long, List<int[]>> pairsByDiff = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                long diff = (long) nums[i] - (long) nums[j];
                pairsByDiff.computeIfAbsent(diff, key -> new ArrayList<>()).add(new int[] {j, i});
            }
        }
        long answer = 0;
        for (List<int[]> pairs : pairsByDiff.values()) {
            long[] weakEndingAt = new long[n];
            for (int[] pair : pairs) {
                int j = pair[0], i = pair[1];
                long completed = weakEndingAt[j];
                answer += completed;
                weakEndingAt[i] += completed + 1;
            }
        }
        return (int) answer;
    }
}

