class Solution {
    public int numberOfArithmeticSlices(int[] nums) {
        int n = nums.length;
        Map<Long, Integer>[] ids = new HashMap[n];
        long[][] counts = new long[n][];
        for (int i = 0; i < n; i++) {
            ids[i] = new HashMap<>();
            for (int j = 0; j < i; j++) {
                long diff = (long) nums[i] - (long) nums[j];
                ids[i].putIfAbsent(diff, ids[i].size());
            }
            counts[i] = new long[ids[i].size()];
        }
        long answer = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                long diff = (long) nums[i] - (long) nums[j];
                Integer previousSlot = ids[j].get(diff);
                long extend = previousSlot == null ? 0 : counts[j][previousSlot];
                int slot = ids[i].get(diff);
                answer += extend;
                counts[i][slot] += extend + 1;
            }
        }
        return (int) answer;
    }
}

