class Solution {
    public int numberOfArithmeticSlices(int[] nums) {
        int n = nums.length;
        Map<Long, List<Integer>> indicesByValue = new HashMap<>();
        for (int i = 0; i < n; i++) {
            indicesByValue.computeIfAbsent((long) nums[i], key -> new ArrayList<>()).add(i);
        }
        long[][] dp = new long[n][n];
        long answer = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                long previousValue = 2L * nums[j] - (long) nums[i];
                List<Integer> candidates = indicesByValue.get(previousValue);
                if (candidates == null) continue;
                for (int k : candidates) {
                    if (k >= j) break;
                    dp[j][i] += dp[k][j] + 1;
                }
                answer += dp[j][i];
            }
        }
        return (int) answer;
    }
}

import java.util.*;

class Solution {
    public int numberOfArithmeticSlices(int[] nums) {
        Map<Long, List<Integer>> positions = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            positions.computeIfAbsent((long) nums[i], key -> new ArrayList<>()).add(i);
        }
        Map<String, Integer> memo = new HashMap<>();
        int answer = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                long diff = (long) nums[j] - (long) nums[i];
                answer += countAfter(j, diff, nums, positions, memo);
            }
        }
        return answer;
    }

    private int countAfter(int last, long diff, int[] nums, Map<Long, List<Integer>> positions, Map<String, Integer> memo) {
        String key = last + "#" + diff;
        Integer cached = memo.get(key);
        if (cached != null) return cached;
        long nextValue = (long) nums[last] + diff;
        List<Integer> nextIndices = positions.get(nextValue);
        int total = 0;
        if (nextIndices != null) {
            for (int next : nextIndices) {
                if (next > last) {
                    total += 1 + countAfter(next, diff, nums, positions, memo);
                }
            }
        }
        memo.put(key, total);
        return total;
    }
}
